1	//! The `config` subcommand: print the settable config schema for a
2	//! target config file (or check it with `--validate`), grouped by
3	//! TOML section, sshd_config style.
4	//!
5	//! - Read-only; consumes `crate::config_schema::schema()` — the
6	//!   single source of truth for every settable key.
7	//! - The positional target is `work`, `bot`, `work,bot` (default),
8	//!   or an explicit config-file path. The user config
9	//!   (`~/.config/vc-x1/config.toml`) has no keyword — reach it by
10	//!   passing its path.
11	//! - The side keywords filter to that side's keys; a path target
12	//!   carries no side information, so it gets the whole schema —
13	//!   no guessing what kind of file the path names.
14	//! - `--validate` checks the target file(s) instead of printing:
15	//!   unknown keys, and — for keyword targets — the legacy-schema
16	//!   rejection plus the resolved-agreement invariant of a dual
17	//!   workspace's `[repos]` registries (via the bot-side
18	//!   resolution).
19	
20	use std::error::Error;
21	use std::path::{Path, PathBuf};
22	
23	use clap::Args;
24	
25	use log::{info, warn};
26	
27	use crate::common::{bot_repo_path, configured_bot_dir, find_workspace_root, reject_legacy_config};
28	use crate::config_schema::{ConfigKey, Home, render_key_block, schema, section_and_leaf};
29	use crate::context::Context;
30	use crate::desc_helpers::VC_CONFIG_FILE;
31	use crate::options_flags::scope::{Scope, Side, parse_scope};
32	use crate::subcommand::SubcommandRunner;
33	use crate::toml_simple::toml_load;
34	
35	/// Parsed positional target: a side keyword set or an explicit
36	/// config-file path.
37	///
38	/// - `Scope` — `work`, `bot`, `work,bot`, `bot,work` (the `--scope`
39	///   grammar), resolved against the surrounding workspace.
40	/// - `Path` — anything else: an explicit config file. The only way
41	///   to reach the user config.
42	#[derive(Clone, Debug, PartialEq)]
43	pub enum ConfigTarget {
44	    Scope(Scope),
45	    Path(PathBuf),
46	}
47	
48	/// Parse the positional target: side keyword form first, else a
49	/// path.
50	///
51	/// A file literally named `work` (etc.) in cwd is shadowed by the
52	/// keyword — target it as `./work`.
53	fn parse_target(s: &str) -> Result<ConfigTarget, String> {
54	    if let Ok(scope) = parse_scope(s) {
55	        return Ok(ConfigTarget::Scope(scope));
56	    }
57	    if s.is_empty() {
58	        return Err("config: target is empty".into());
59	    }
60	    Ok(ConfigTarget::Path(PathBuf::from(s)))
61	}
62	
63	#[derive(Args, Debug)]
64	pub struct ConfigArgs {
65	    /// What to print or validate: side keyword(s) `work`, `bot`,
66	    /// `work,bot`, or a config-file path. The user config
67	    /// (`~/.config/vc-x1/config.toml`) has no keyword — pass its
68	    /// path.
69	    #[arg(value_parser = parse_target, default_value = "work,bot", verbatim_doc_comment)]
70	    pub target: ConfigTarget,
71	
72	    /// Check the target config file(s) — unknown/misspelled keys,
73	    /// legacy-schema rejection, [repos] resolved-agreement
74	    /// invariant — instead of printing the schema
75	    #[arg(long)]
76	    pub validate: bool,
77	}
78	
79	/// Inputs to the `config` op, flat, owned, clap-free.
80	///
81	/// Mirrors `ConfigArgs`: positional target (`target`), `--validate`
82	/// (`validate`).
83	pub struct ConfigParams {
84	    pub target: ConfigTarget,
85	    pub validate: bool,
86	}
87	
88	impl From<&ConfigArgs> for ConfigParams {
89	    /// Convert clap-derived `ConfigArgs` into the flat
90	    /// `ConfigParams` (total — every field copies straight over).
91	    fn from(a: &ConfigArgs) -> Self {
92	        Self {
93	            target: a.target.clone(),
94	            validate: a.validate,
95	        }
96	    }
97	}
98	
99	impl SubcommandRunner for ConfigArgs {
100	    type Params = ConfigParams;
101	
102	    /// Delegate to the existing `From<&ConfigArgs>` impl above
103	    /// (total — never fails).
104	    fn to_params(&self) -> Result<Self::Params, String> {
105	        Ok(ConfigParams::from(self))
106	    }
107	
108	    /// Run the `config` op.
109	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
110	        config(ctx, params)
111	    }
112	}
113	
114	/// A key is settable on the work side if its homes include
115	/// `Home::WorkspaceCode`.
116	fn in_work_side(homes: &[Home]) -> bool {
117	    homes.contains(&Home::WorkspaceCode)
118	}
119	
120	/// A key is settable on the bot side if its homes include
121	/// `Home::WorkspaceBot`.
122	fn in_bot_side(homes: &[Home]) -> bool {
123	    homes.contains(&Home::WorkspaceBot)
124	}
125	
126	/// Every key — a path target carries no side information, so it
127	/// prints/validates against the whole schema, no guessing.
128	fn in_any(_homes: &[Home]) -> bool {
129	    true
130	}
131	
132	/// Print one target group: a divider (`header` verbatim), then each
133	/// key grouped by section (schema order, first-seen section order),
134	/// one `[section]` header per section. Each key renders as a
135	/// multi-line doc-block via `render_key_block` (shared with
136	/// `crate::init`'s generated `.vc-config.toml`).
137	fn print_group(header: &str, keys: &[&ConfigKey]) {
138	    info!("# ── {header} ──");
139	    let mut sections: Vec<&str> = Vec::new();
140	    for key in keys {
141	        let (section, _leaf) = section_and_leaf(key.path);
142	        if !sections.contains(&section) {
143	            sections.push(section);
144	        }
145	    }
146	    for section in sections {
147	        info!("[{section}]");
148	        for key in keys {
149	            let (key_section, _leaf) = section_and_leaf(key.path);
150	            if key_section != section {
151	                continue;
152	            }
153	            for line in render_key_block(key).lines() {
154	                info!("{line}");
155	            }
156	        }
157	    }
158	    info!("");
159	}
160	
161	/// True if `actual` (a config key from a loaded config file) is
162	/// recognized by some `schema()` entry whose homes satisfy
163	/// `home_pred`.
164	///
165	/// - Non-dynamic entries match by exact path equality.
166	/// - Dynamic entries (`key.dynamic`) match segment-wise: equal
167	///   segment counts, each entry segment either equal to the actual
168	///   segment or a `<placeholder>` matching any single segment.
169	fn key_known(actual: &str, home_pred: fn(&[Home]) -> bool) -> bool {
170	    schema().iter().any(|key| {
171	        if !home_pred(key.homes) {
172	            return false;
173	        }
174	        if !key.dynamic {
175	            return key.path == actual;
176	        }
177	        let entry_segs: Vec<&str> = key.path.split('.').collect();
178	        let actual_segs: Vec<&str> = actual.split('.').collect();
179	        entry_segs.len() == actual_segs.len()
180	            && entry_segs
181	                .iter()
182	                .zip(actual_segs.iter())
183	                .all(|(e, a)| e == a || (e.starts_with('<') && e.ends_with('>')))
184	    })
185	}
186	
187	/// Validate one config file against the schema, filtered to the
188	/// homes accepted at that file by `home_pred`.
189	///
190	/// - A missing file is not an error — `info!`s that it's absent
191	///   and returns `Ok(0)`.
192	/// - Each key not recognized by `key_known` is reported with
193	///   `warn!`, naming `label` and the key; keys are checked in
194	///   sorted order for stable output.
195	/// - Returns the count of unknown keys found. A load error
196	///   (malformed TOML) propagates as `Err`.
197	fn validate_file(
198	    path: &Path,
199	    label: &str,
200	    home_pred: fn(&[Home]) -> bool,
201	) -> Result<usize, Box<dyn Error>> {
202	    if !path.exists() {
203	        info!("{label}: {} not found — skipping", path.display());
204	        return Ok(0);
205	    }
206	    let map = toml_load(path)?;
207	    let mut keys: Vec<&String> = map.keys().collect();
208	    keys.sort();
209	
210	    let mut unknown = 0;
211	    for key in keys {
212	        if !key_known(key, home_pred) {
213	            warn!("{label} ({}): unknown key {key:?}", path.display());
214	            unknown += 1;
215	        }
216	    }
217	    Ok(unknown)
218	}
219	
220	/// Validate the target's config file(s), returning the total count
221	/// of problems found (unknown keys, legacy/grammar rejections,
222	/// workspace-coherence failures).
223	///
224	/// - Keyword targets resolve against `root`; outside a workspace
225	///   there is nothing to check (info + `Ok(0)`).
226	/// - The bot side resolves via `bot_repo_path`, which runs the
227	///   dual-preflight coherence check (bot dir exists, both configs
228	///   load, resolved `[repos]` agreement) — its failure is
229	///   reported as a finding, not a hard error, so the work-side
230	///   report still lands.
231	/// - A path target carries no side information, so it validates
232	///   against the whole schema (any home's keys accepted).
233	fn validate(params: &ConfigParams, root: Option<&Path>) -> Result<usize, Box<dyn Error>> {
234	    let mut findings = 0;
235	    match &params.target {
236	        ConfigTarget::Scope(scope) => {
237	            let Some(root) = root else {
238	                info!("not inside a workspace — nothing to validate");
239	                return Ok(0);
240	            };
241	            if let Err(e) = reject_legacy_config(root) {
242	                // One finding, reported once: a legacy schema makes
243	                // the remaining checks redundant — the unknown-key
244	                // scan would re-flag the legacy keys and the
245	                // bot-side resolution would re-print this same
246	                // rejection.
247	                warn!("{e}");
248	                return Ok(1);
249	            }
250	            for side in &scope.0 {
251	                match side {
252	                    Side::Work => {
253	                        findings +=
254	                            validate_file(&root.join(VC_CONFIG_FILE), "work config", in_work_side)?;
255	                    }
256	                    Side::Bot => match bot_repo_path(root) {
257	                        Ok(Some(bot)) => {
258	                            findings += validate_file(
259	                                &bot.join(VC_CONFIG_FILE),
260	                                "bot config",
261	                                in_bot_side,
262	                            )?;
263	                        }
264	                        Ok(None) => info!("bot config: no bot repo configured — skipping"),
265	                        Err(e) => {
266	                            warn!("{e}");
267	                            findings += 1;
268	                        }
269	                    },
270	                }
271	            }
272	        }
273	        ConfigTarget::Path(path) => {
274	            findings += validate_file(path, "config file", in_any)?;
275	        }
276	    }
277	    Ok(findings)
278	}
279	
280	/// Print the settable config schema for the target: one group per
281	/// resolved side (keyword target) or one group for the named file
282	/// (path target), with the resolved file path as the group hint
283	/// when the workspace provides one.
284	fn print_schema(params: &ConfigParams, root: Option<&Path>) {
285	    info!(
286	        "# vc-x1 settable config keys (from vc-x1 {})",
287	        env!("CARGO_PKG_VERSION")
288	    );
289	    info!("# Keys below are shown at their built-in default (commented");
290	    info!("# unless required); run `vc-x1 config --validate` to check a");
291	    info!("# config file's keys against this schema.");
292	    info!("");
293	
294	    let all = schema();
295	    let group = |pred: fn(&[Home]) -> bool| -> Vec<&ConfigKey> {
296	        all.iter().filter(|k| pred(k.homes)).collect()
297	    };
298	
299	    match &params.target {
300	        ConfigTarget::Scope(scope) => {
301	            for side in &scope.0 {
302	                match side {
303	                    Side::Work => {
304	                        let hint = match root {
305	                            Some(r) => r.join(VC_CONFIG_FILE).display().to_string(),
306	                            None => format!("<root>/{VC_CONFIG_FILE}"),
307	                        };
308	                        print_group(&format!("work: {hint}"), &group(in_work_side));
309	                    }
310	                    Side::Bot => {
311	                        let bot = root.and_then(|r| configured_bot_dir(r).ok().flatten());
312	                        let hint = match bot {
313	                            Some(b) => b.join(VC_CONFIG_FILE).display().to_string(),
314	                            None => format!("<root>/<bot-dir>/{VC_CONFIG_FILE}"),
315	                        };
316	                        print_group(&format!("bot: {hint}"), &group(in_bot_side));
317	                    }
318	                }
319	            }
320	        }
321	        ConfigTarget::Path(path) => {
322	            print_group(&path.display().to_string(), &group(in_any));
323	        }
324	    }
325	}
326	
327	/// Print the settable config schema for the target (default), or —
328	/// with `--validate` — check the target's config file(s) and exit
329	/// non-zero if any problem is found.
330	pub fn config(_ctx: &Context, params: &ConfigParams) -> Result<(), Box<dyn std::error::Error>> {
331	    let root = find_workspace_root();
332	    if params.validate {
333	        let total = validate(params, root.as_deref())?;
334	        return if total > 0 {
335	            Err(format!("config: {total} problem(s) found").into())
336	        } else {
337	            info!("config: all checks passed");
338	            Ok(())
339	        };
340	    }
341	    print_schema(params, root.as_deref());
342	    Ok(())
343	}
344	
