427	    #[test]
428	    fn validate_dual_workspace_clean() {
429	        let fx = Fixture::new("config-validate-clean");
430	        let params = ConfigParams {
431	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
432	            validate: true,
433	        };
434	        let findings = validate(&params, Some(&fx.work)).expect("validate");
435	        assert_eq!(findings, 0);
436	    }
