438	    #[test]
439	    fn validate_flags_unknown_key() {
440	        let fx = Fixture::new("config-validate-unknown");
441	        append(
442	            &fx.work.join(VC_CONFIG_FILE),
443	            "\n[bogus-section]\nkey = \"v\"\n",
444	        );
445	        let params = ConfigParams {
446	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
447	            validate: true,
448	        };
449	        let findings = validate(&params, Some(&fx.work)).expect("validate");
450	        assert_eq!(findings, 1);
451	    }
