453	    #[test]
454	    fn validate_flags_incoherent_workspace_blocks() {
455	        // Diverge the bot side's [repos] registry (its bot entry
456	        // resolves to a different dir): the bot-side resolution
457	        // runs the dual-preflight coherence check, which must
458	        // surface as a finding (not a hard error) so the
459	        // work-side report still lands.
460	        let fx = Fixture::new("config-validate-incoherent");
461	        std::fs::create_dir_all(fx.work.join("other")).expect("mkdir other");
462	        std::fs::write(
463	            fx.bot.join(VC_CONFIG_FILE),
464	            "[repos]\nwork = \"..\"\nbot = \"../other\"\n",
465	        )
466	        .expect("rewrite bot config");
467	        let params = ConfigParams {
468	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
469	            validate: true,
470	        };
471	        let findings = validate(&params, Some(&fx.work)).expect("validate");
472	        assert_eq!(findings, 1);
473	    }
474	
475	    #[test]
476	    fn validate_legacy_schema_is_one_finding() {
477	        // A legacy schema short-circuits: one warn, one finding —
478	        // no unknown-key re-flagging of the legacy keys, no
479	        // repeated rejection via the bot-side resolution.
480	        let ts = std::time::SystemTime::now()
481	            .duration_since(std::time::UNIX_EPOCH)
482	            .map(|d| d.as_nanos())
483	            .unwrap_or(0);
484	        let root = std::env::temp_dir().join(format!("vc-x1-config-legacy-{ts}"));
485	        std::fs::create_dir_all(&root).expect("mkdir");
486	        std::fs::write(
487	            root.join(VC_CONFIG_FILE),
488	            "[workspace]\npath = \"/\"\nother-repo = \".claude\"\n",
489	        )
490	        .expect("write legacy config");
491	        let params = ConfigParams {
492	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
493	            validate: true,
494	        };
495	        let findings = validate(&params, Some(&root)).expect("validate");
496	        assert_eq!(findings, 1);
497	        std::fs::remove_dir_all(&root).ok();
498	    }
499	
500	    #[test]
501	    fn validate_single_repo_skips_bot_side() {
502	        let fx = FixturePor::new("config-validate-por");
503	        let params = ConfigParams {
504	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
505	            validate: true,
506	        };
507	        let findings = validate(&params, Some(&fx.work)).expect("validate");
508	        assert_eq!(findings, 0);
509	    }
510	
511	    #[test]
512	    fn validate_outside_workspace_is_clean() {
513	        let params = ConfigParams {
514	            target: ConfigTarget::Scope(Scope(vec![Side::Work, Side::Bot])),
515	            validate: true,
516	        };
517	        let findings = validate(&params, None).expect("validate");
518	        assert_eq!(findings, 0);
519	    }
520	
521	    #[test]
522	    fn validate_explicit_path_target() {
523	        let fx = Fixture::new("config-validate-path");
524	        let path = fx.work.join(VC_CONFIG_FILE);
525	        append(&path, "\n[bogus-section]\nkey = \"v\"\n");
526	        let params = ConfigParams {
527	            target: ConfigTarget::Path(path),
528	            validate: true,
529	        };
530	        let findings = validate(&params, Some(&fx.work)).expect("validate");
531	        assert_eq!(findings, 1);
532	    }
533	}
