1	//! Shared core for the `validate-todo` / `fix-todo` subcommands:
2	//! parse `TODO.md`'s numbered sections and compute the
3	//! renumber / re-indent plan.
4	//!
5	//! - `## Todo` and `## Bugs` hold manually-numbered entries
6	//!   (`1.` `2.` ... at column 0); every other section is skipped.
7	//! - `analyze` walks the file once: it returns one `Change` per
8	//!   entry whose number or continuation indent is off, plus the
9	//!   fully renumbered / re-indented file content.
10	//! - Continuation indent is normalized against each entry's
11	//!   *measured* base indent, so nested `- ` sub-bullets keep
12	//!   their relative depth.
13	
14	/// Default todo file, relative to the workspace root.
15	pub const TODO_FILE: &str = "TODO.md";
16	
17	/// A manually-numbered section of the todo file.
18	#[derive(Clone, Copy, PartialEq, Eq, Debug)]
19	pub enum Section {
20	    /// The `## Todo` backlog list.
21	    Todo,
22	    /// The `## Bugs` list.
23	    Bugs,
24	}
25	
26	impl Section {
27	    /// The section's markdown header text (`## Todo` / `## Bugs`).
28	    pub fn header(self) -> &'static str {
29	        match self {
30	            Section::Todo => "## Todo",
31	            Section::Bugs => "## Bugs",
32	        }
33	    }
34	}
35	
36	/// One entry whose number and/or continuation indent needs to
37	/// change for the section to be sequentially numbered.
38	///
39	/// - `num_old` / `num_new` — the displayed number and its
40	///   sequential (1-based) position; equal when only the indent is
41	///   off.
42	/// - `new_first_line` — the entry's first line with the corrected
43	///   number.
44	/// - `indent_old` / `indent_new` — the measured continuation-base
45	///   indent and the expected one (the number prefix's width);
46	///   both `None` when the entry has no continuation lines.
47	pub struct Change {
48	    pub section: Section,
49	    pub line_no: usize,
50	    pub new_first_line: String,
51	    pub num_old: usize,
52	    pub num_new: usize,
53	    pub indent_old: Option<usize>,
54	    pub indent_new: Option<usize>,
55	}
56	
57	/// Result of scanning a todo file: per-section entry counts, the
58	/// entries needing a fix, and the fully corrected file content.
59	pub struct Analysis {
60	    pub todo_count: usize,
61	    pub bugs_count: usize,
62	    pub changes: Vec<Change>,
63	    pub fixed: String,
64	}
65	
66	/// An entry being accumulated during the `analyze` walk — its
67	/// `N. ` number, that line minus its prefix, and the raw
68	/// continuation lines (blank lines included).
69	struct PendingEntry {
70	    section: Section,
71	    line_no: usize,
72	    num_old: usize,
73	    num_new: usize,
74	    rest: String,
75	    cont: Vec<String>,
76	}
77	
78	/// Number of decimal digits in `n` (entry numbers are ≥ 1).
79	fn digit_count(n: usize) -> usize {
80	    n.to_string().len()
81	}
82	
83	/// Count of leading ASCII spaces on `line`.
84	fn leading_spaces(line: &str) -> usize {
85	    line.len() - line.trim_start_matches(' ').len()
86	}
87	
88	/// Returns `entry` / `entries` — the count noun for `n`.
89	pub fn entry_word(n: usize) -> &'static str {
90	    if n == 1 { "entry" } else { "entries" }
91	}
92	
93	/// Build the `[line: ...]` tag for an entry — its line number,
94	/// then what changed (`was N`, `indent A -> B`, or both). Used by
95	/// `validate-todo` and `fix-todo` for the same per-entry line.
96	pub fn change_tag(c: &Change) -> String {
97	    let mut parts: Vec<String> = Vec::new();
98	    if c.num_old != c.num_new {
99	        parts.push(format!("was {}", c.num_old));
100	    }
101	    if let (Some(o), Some(n)) = (c.indent_old, c.indent_new)
102	        && o != n
103	    {
104	        parts.push(format!("indent {o} -> {n}"));
105	    }
106	    format!("[{}: {}]", c.line_no, parts.join(", "))
107	}
108	
109	/// Classify a line as a `## ` section header.
110	///
111	/// - `None` — not a level-2 header (covers `# `, `### `, body
112	///   text).
113	/// - `Some(None)` — a `## ` header that isn't `## Todo` /
114	///   `## Bugs` (e.g. `## In Progress`, `## Done`).
115	/// - `Some(Some(section))` — the `## Todo` or `## Bugs` header.
116	fn section_header(line: &str) -> Option<Option<Section>> {
117	    if !line.starts_with("## ") {
118	        return None;
119	    }
120	    Some(match line.trim_end() {
121	        "## Todo" => Some(Section::Todo),
122	        "## Bugs" => Some(Section::Bugs),
123	        _ => None,
124	    })
125	}
126	
