128	///
129	/// Returns `(number, prefix_len)` — the entry number and the byte
130	/// length of the `N. ` prefix — when `line` begins with one or
131	/// more ASCII digits followed by `". "` (the renumber
132	/// convention's `^\d+\. ` anchor). Returns `None` for intro lines
133	/// (which carry a leading space), continuation lines, and
134	/// headings.
135	fn parse_entry_prefix(line: &str) -> Option<(usize, usize)> {
136	    let bytes = line.as_bytes();
137	    let mut i = 0;
138	    while i < bytes.len() && bytes[i].is_ascii_digit() {
139	        i += 1;
140	    }
141	    if i == 0 || bytes.get(i) != Some(&b'.') || bytes.get(i + 1) != Some(&b' ') {
142	        return None;
143	    }
144	    let num: usize = line[..i].parse().ok()?;
145	    Some((num, i + 2))
146	}
