149	/// and, when the number or continuation indent changed, push a
150	/// `Change`.
151	///
152	/// The continuation block is shifted as a whole by
153	/// `prefix_width − measured_base`, so a deliberately nested
154	/// sub-bullet keeps its depth relative to the entry's base.
155	fn finish_entry(p: PendingEntry, changes: &mut Vec<Change>, out: &mut Vec<String>) {
