157	    let new_first_line = format!("{}. {}", p.num_new, p.rest);
158	
159	    // Measured base = minimum indent of the *indented* non-blank
160	    // continuation lines. A column-0 line can't be a real list
161	    // continuation (continuations must be indented), so it's
162	    // excluded from the base and emitted verbatim below — a stray
163	    // one doesn't drag the base down to 0.
