172	        Some(b) => (Some(b), Some(prefix_width)),
173	        None => (None, None),
174	    };
175	
176	    out.push(new_first_line.clone());
177	    let delta: isize = base.map_or(0, |b| prefix_width as isize - b as isize);
178	    for line in &p.cont {
179	        let indent = leading_spaces(line);
180	        if line.trim().is_empty() || indent == 0 {
181	            // Blank line, or a column-0 line that isn't a real
182	            // continuation — pass through unchanged.
183	            out.push(line.clone());
184	        } else {
185	            let shifted = (indent as isize + delta).max(0) as usize;
186	            out.push(format!(
187	                "{}{}",
188	                " ".repeat(shifted),
189	                line.trim_start_matches(' ')
190	            ));
191	        }
192	    }
193	
194	    if p.num_old != p.num_new || indent_old != indent_new {
195	        changes.push(Change {
196	            section: p.section,
197	            line_no: p.line_no,
198	            new_first_line,
199	            num_old: p.num_old,
200	            num_new: p.num_new,
201	            indent_old,
202	            indent_new,
203	        });
204	    }
205	}
