217	///   content with every entry renumbered and re-indented. `fixed`
218	///   round-trips an already-correct file unchanged.
219	pub fn analyze(content: &str) -> Analysis {
220	    let mut changes = Vec::new();
221	    let mut out: Vec<String> = Vec::new();
222	    let mut todo_count = 0;
223	    let mut bugs_count = 0;
224	    let mut section: Option<Section> = None;
225	    let mut entry_idx = 0usize;
226	    let mut pending: Option<PendingEntry> = None;
